9	// syntheticRecord fingerprints one record exactly as the store would,
10	// letting tests build chains that can never occur through the live API
11	// (e.g. a decision naming a version published later).
12	func syntheticRecord(org string, seq int, kind string, change *PolicyChange, decision *DecisionRecord, prev string) AuditRecord {
13		r := AuditRecord{
14			Org:             org,
15			Seq:             seq,
16			Kind:            kind,
17			Change:          change,
18			Decision:        decision,
19			PrevFingerprint: prev,
20		}
21		r.Fingerprint = fingerprintFor(&r)
22		return r
23	}
