517	// offlineBadRequest returns a request that fails exactly one envelope
518	// condition when reviewed for org, together with the online reason.
519	func offlineBadRequestCases(org string) map[string]struct {
520		modify func(OrgRequest) OrgRequest
521		reason string
522	} {
523		return map[string]struct {
524			modify func(OrgRequest) OrgRequest
525			reason string
526		}{
527			"disabled subject": {
528				modify: func(r OrgRequest) OrgRequest { r.Subject.Disabled = true; return r },
529				reason: "subject is disabled",
530			},
