package main

import (
	"flag"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

func main() {
	command := "demo"
	if len(os.Args) > 1 {
		command = os.Args[1]
	}
	switch command {
	case "demo":
		runDemo()
	case "review":
		runReview(os.Args[2:])
	case "version":
		fmt.Println("darksafe 0.1.0")
