	} {
		if value == "" {
			missing = append(missing, "-"+name)
		}
	}
	if len(missing) > 0 {
		fmt.Fprintf(os.Stderr, "review: missing required inputs: %s\n", strings.Join(missing, ", "))
		reviewUsage()
		os.Exit(2)
	}

	seq := parseReviewInt("-seq", *seqRaw)
